local SurgicalToolMaker = {}
local PRODUCTS = {
    iron_scalpel = { name = "Železen skalpel", ironCost = 1, woodCost = 1, time = 2, cost = 25, sharpness = 50, description = "Železen skalpel za operacije." },
    steel_scalpel = { name = "Jeklen skalpel", steelCost = 1, woodCost = 1, time = 3, cost = 60, sharpness = 65, prestige = 2, description = "Jeklen skalpel za natančne reze." },
    silver_forceps = { name = "Srebrne pincete", silverCost = 1, steelCost = 1, time = 4, cost = 120, sharpness = 75, prestige = 4, happiness = 1, description = "Srebrne pincete za ekstrakcijo." },
    silver_surgical_kit = { name = "Srebrni kirurški komplet", silverCost = 2, steelCost = 1, woodCost = 1, time = 7, cost = 280, sharpness = 85, prestige = 9, happiness = 2, description = "Srebrni kirurški komplet za zdravnike." },
    gold_trim_surgical_kit = { name = "Zlatorobni kirurški komplet", goldCost = 1, silverCost = 1, steelCost = 1, jewelCost = 1, time = 10, cost = 620, sharpness = 92, prestige = 16, happiness = 4, description = "Zlatorobni kirurški komplet za kraljeve zdravnike." },
    royal_grand_surgical = { name = "Kraljevski veliki kirurški komplet", goldCost = 2, silverCost = 1, steelCost = 2, jewelCost = 1, pearlCost = 1, time = 15, cost = 1600, sharpness = 100, prestige = 38, happiness = 8, description = "Veliki kraljevski kirurški komplet z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Kirurška delavnica", cost = { gold = 300, wood = 130, stone = 250 }, upkeep = 8, qualityBonus = 5 },
    forge = { name = "Kirurška kovačija", cost = { gold = 1000, wood = 280, stone = 500, steel = 8 }, upkeep = 25, qualityBonus = 18 },
    sharpening_room = { name = "Brusilnica", cost = { gold = 2400, wood = 350, stone = 700, silver = 30, iron = 8 }, upkeep = 60, qualityBonus = 30 },
    royal_surgical_atelier = { name = "Kraljevski atelje kirurgije", cost = { gold = 9500, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
SurgicalToolMaker.ironStock = 14; SurgicalToolMaker.steelStock = 12; SurgicalToolMaker.woodStock = 14; SurgicalToolMaker.silverStock = 8; SurgicalToolMaker.goldStock = 6; SurgicalToolMaker.jewelStock = 6; SurgicalToolMaker.pearlStock = 4
SurgicalToolMaker.productStock = {}; SurgicalToolMaker.buildings = {}; SurgicalToolMaker.maker = nil; SurgicalToolMaker.activeMaking = {}; SurgicalToolMaker.totalProducts = 0; SurgicalToolMaker.dayTimer = 0
function SurgicalToolMaker.init() SurgicalToolMaker.ironStock=14; SurgicalToolMaker.steelStock=12; SurgicalToolMaker.woodStock=14; SurgicalToolMaker.silverStock=8; SurgicalToolMaker.goldStock=6; SurgicalToolMaker.jewelStock=6; SurgicalToolMaker.pearlStock=4; SurgicalToolMaker.productStock={}; SurgicalToolMaker.buildings={}; SurgicalToolMaker.maker=nil; SurgicalToolMaker.activeMaking={}; SurgicalToolMaker.totalProducts=0; SurgicalToolMaker.dayTimer=0; print("[SurgicalToolMaker] Royal Surgical Tool Maker System initialized (6 products, 4 buildings)") end
function SurgicalToolMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SurgicalToolMaker.maker={name=n or ("Kirurški kovač "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kirurški kovač najet: %s (spretnost: %d)",SurgicalToolMaker.maker.name,s),"success") end; return true end
function SurgicalToolMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SurgicalToolMaker.build(id) local ok,e=SurgicalToolMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SurgicalToolMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SurgicalToolMaker.getQualityBonus() local b=0; for _,bd in ipairs(SurgicalToolMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SurgicalToolMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SurgicalToolMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and SurgicalToolMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and SurgicalToolMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and SurgicalToolMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SurgicalToolMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SurgicalToolMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SurgicalToolMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SurgicalToolMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SurgicalToolMaker.maker then return false,"Potreben kirurški kovač" end; return true end
function SurgicalToolMaker.make(pt,qty) qty=qty or 1; local ok,e=SurgicalToolMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SurgicalToolMaker.ironStock=SurgicalToolMaker.ironStock-d.ironCost*qty end; if d.steelCost then SurgicalToolMaker.steelStock=SurgicalToolMaker.steelStock-d.steelCost*qty end; if d.woodCost then SurgicalToolMaker.woodStock=SurgicalToolMaker.woodStock-d.woodCost*qty end; if d.silverCost then SurgicalToolMaker.silverStock=SurgicalToolMaker.silverStock-d.silverCost*qty end; if d.goldCost then SurgicalToolMaker.goldStock=SurgicalToolMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SurgicalToolMaker.jewelStock=SurgicalToolMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SurgicalToolMaker.pearlStock=SurgicalToolMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SurgicalToolMaker.maker then t=math.max(1,t-math.floor(SurgicalToolMaker.maker.skill/12)) end; table.insert(SurgicalToolMaker.activeMaking,{id="surgical_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sharpness=d.sharpness or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SurgicalToolMaker.completeMaking(m) local q=1.0+(SurgicalToolMaker.getQualityBonus()/100); if SurgicalToolMaker.maker then q=q+(SurgicalToolMaker.maker.skill/150) end; q=math.min(2.5,q); SurgicalToolMaker.productStock[m.productType]=(SurgicalToolMaker.productStock[m.productType] or 0)+m.quantity; SurgicalToolMaker.totalProducts=SurgicalToolMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SurgicalToolMaker.maker then SurgicalToolMaker.maker.itemsMade=SurgicalToolMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SurgicalToolMaker.maker.skill=math.min(100,SurgicalToolMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kirurško orodje izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"surgical.completed",{productName=m.productName,sharpness=m.sharpness,prestige=m.prestige,happiness=m.happiness}) end end
function SurgicalToolMaker.update(dt) if not _G.state then return end; SurgicalToolMaker.dayTimer=SurgicalToolMaker.dayTimer+dt; if SurgicalToolMaker.dayTimer>=30 then SurgicalToolMaker.dayTimer=0; for i=#SurgicalToolMaker.activeMaking,1,-1 do local m=SurgicalToolMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SurgicalToolMaker.completeMaking(m); table.remove(SurgicalToolMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SurgicalToolMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SurgicalToolMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SurgicalToolMaker.getStats() return {ironStock=SurgicalToolMaker.ironStock,steelStock=SurgicalToolMaker.steelStock,woodStock=SurgicalToolMaker.woodStock,silverStock=SurgicalToolMaker.silverStock,goldStock=SurgicalToolMaker.goldStock,jewelStock=SurgicalToolMaker.jewelStock,pearlStock=SurgicalToolMaker.pearlStock,productStock=SurgicalToolMaker.productStock,numBuildings=#SurgicalToolMaker.buildings,hasMaker=SurgicalToolMaker.maker~=nil,makerName=SurgicalToolMaker.maker and SurgicalToolMaker.maker.name or "—",makerSkill=SurgicalToolMaker.maker and SurgicalToolMaker.maker.skill or 0,activeMaking=#SurgicalToolMaker.activeMaking,totalProducts=SurgicalToolMaker.totalProducts} end
return SurgicalToolMaker
